struct RTree {
    using variant_type = ::tpy::Union<A, int32_t, std::vector<RTree>, std::string>;
    variant_type value;

    RTree() = default;
    template<typename T>
        requires std::constructible_from<variant_type, T&&>
    RTree(T&& v) : value(std::forward<T>(v)) {}

    bool operator==(const RTree&) const = default;

    friend std::ostream& operator<<(std::ostream& os, const RTree& v) {
        ::tpy::detail::print_element(os, v.value);
        return os;
    }
};


